contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address first, address second) public payable {
        require(first != second);

        c.getFirstWithdrawalBonus(first); if (__ESBMC_reverted()) return;

        uint contractAfterFirst = address(c).balance;
        uint firstAfter = first.balance;
        uint secondBefore = second.balance;

        c.withdrawReward(second); if (__ESBMC_reverted()) return;

        uint contractAfterSecond = address(c).balance;
        uint secondAfter = second.balance;

        assert(
            contractAfterSecond == contractAfterFirst &&
            secondAfter == secondBefore &&
            firstAfter >= 100
        );
    }

    receive() external payable {}
}

