// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address first, address second) internal {
        vm.assume(first != second);
        try c.getFirstWithdrawalBonus(first) {} catch { return; }
        uint contractAfterFirst = address(c).balance;
        uint firstAfter = first.balance;
        uint secondBefore = second.balance;
        try c.withdrawReward(second) {} catch { return; }
        uint contractAfterSecond = address(c).balance;
        uint secondAfter = second.balance;
        assertTrue(contractAfterSecond == contractAfterFirst &&
            secondAfter == secondBefore &&
            firstAfter >= 100);
    }

    function testFuzz_run(address first, address second) public {
        vm.assume(first.code.length == 0 && uint160(first) > 0xffff && first != address(this) && first != address(c) && first != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && first != 0x000000000000000000636F6e736F6c652e6c6f67 && first != 0x4e59b44847b379578588920cA78FbF26c0B4956C && first != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(second.code.length == 0 && uint160(second) > 0xffff && second != address(this) && second != address(c) && second != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && second != 0x000000000000000000636F6e736F6c652e6c6f67 && second != 0x4e59b44847b379578588920cA78FbF26c0B4956C && second != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(first, second);
    }

    receive() external payable {}
}
